function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 1000) return 'nums needs 2 to 1000 values.';
  if (nums.length % 2 !== 0) return 'nums must have an even length.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 500)) return 'Each value is an integer from 1 to 500.';
  return null;
}

