function generate(rand, size) {
  const n = size === 'large' ? 300 + Math.floor(rand() * 201) : 1 + Math.floor(rand() * 5);
  const span = size === 'large' ? 500 : 1 + Math.floor(rand() * 4);
  const pick = () => 1 + Math.floor(rand() * span);
  const nums = [];
  if (rand() < 0.5) {
    for (let i = 0; i < n; i++) {
      const value = pick();
      nums.push(value, value);
    }
    if (rand() < 0.4) nums[Math.floor(rand() * nums.length)] = pick();
  } else {
    for (let i = 0; i < 2 * n; i++) nums.push(pick());
  }
  for (let i = nums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
